for stim_name in stim_names:
    types = list(set([stims[stim_name].type() for stims in stim_list if stim_name in stims]))
    if len(types)>1:
        nl.notify('Error: Trying to stack stimuli of different types! (%s)' % stim_name,level=nl.level.error)
