def validate_deserialize(rawmsg, requrl=None, check_expiration=True,
                         decode_payload=True, algorithm_name=DEFAULT_ALGO):
    """
    Validate a JWT compact serialization and return the header and
    payload if the signature is good.

    If check_expiration is False, the payload will be accepted even if
    expired.

    If decode_payload is True then this function will attempt to decode
    it as JSON, otherwise the raw payload will be returned. Note that
    it is always decoded from base64url.
    """
    if not isinstance(rawmsg, str):
        raise TypeError('rawmsg must be a string')
    if not rawmsg:
        raise ValueError('rawmsg must not be empty')

    # Split the message into header, payload, and signature
    try:
        header, payload, signature = rawmsg.split('.')
    except ValueError:
        raise InvalidTokenError('Malformed JWT')

    # Decode the header and payload
    try:
        header = base64url_decode(header.encode('ascii'))
        payload = base64url_decode(payload.encode('ascii'))
    except (TypeError, binascii.Error):
        raise InvalidTokenError('Malformed JWT')

    # Validate the header
    try:
        header = json.loads(header.decode('ascii'))
    except (TypeError, ValueError):
        raise InvalidTokenError('Malformed JWT')

    # Validate the payload
    try:
        payload = json.loads(payload.decode('ascii'))
    except (TypeError, ValueError):
        raise InvalidTokenError('Malformed JWT')

    # Validate the signature
    if not verify_signature(rawmsg, requrl, algorithm_name):
        raise InvalidTokenError('Signature verification failed')

    # Validate the expiration time
    if check_expiration and 'exp' in payload:
        if payload['exp'] < time.time():
            raise ExpiredTokenError('Token has expired')

    # Validate the issuer
    if 'iss' in payload:
        if not isinstance(payload['iss'], str):
            raise InvalidTokenError('Invalid issuer')

