def map_(input_layer, fn):
  """Maps the given function across this sequence.

  To map an entire template across the sequence, use the `as_fn` method on the
  template.

  Args:
    input_layer: The input tensor.
    fn: A function of 1 argument that is applied to each item in the sequence.
  Returns:
    A new sequence Pretty Tensor.
  Raises:
    ValueError: If the input_layer does not hold a sequence.
  """
  if not isinstance(input_layer, pretty_tensor.PrettyTensor):
    raise ValueError('Input layer must be a Pretty Tensor.')
  if not isinstance(fn, pretty_tensor.PrettyTensor):
    raise ValueError('Function must be a Pretty Tensor.')
  if input_layer.shape.ndims!= 1:
    raise ValueError('Input layer must be a sequence.')
  if fn.shape.ndims!= 1:
    raise ValueError('Function must be a sequence.')
