def parse(cls, args):
        """
        Parse command line arguments to construct a dictionary of command
        parameters that can be used to create a command

        Args:
            `args`: sequence of arguments

        Returns:
            Dictionary that can be used in create method

        Raises:
            ParseError: when the arguments are not correct
        """
            if len(args) < 2:
                raise ParseError("Not enough arguments")

            command = args[0]
            if command not in cls.commands:
                raise ParseError("Unknown command")

            params = {}
            for i in range(1, len(args)):
                if args[i].startswith("--"):
                    if "=" in args[i]:
                        key, value = args[i].split("=", 1)
                        params[key] = value
                    else:
                        params[args[i]] = True
                else:
                    params[cls.commands[command]] = args[i]

            return params

