def validate_token(self, token, scopes_required=None):
        """
        This function can be used to validate tokens.

        Note that this only works if a token introspection url is configured,
        as that URL will be queried for the validity and scopes of a token.

        :param scopes_required: List of scopes that are required to be
            granted by the token before returning True.
        :type scopes_required: list

        :returns: True if the token was valid and contained the required
            scopes. An ErrStr (subclass of string for which bool() is False) if
            an error occured.
        :rtype: Boolean or String

        .. versionadded:: 1.1
        """
        :rtype: bool or ErrStr
               """
               if not self.token_introspection_url:
                   return ErrStr("No token introspection URL configured.")

               try:
                   response = requests.post(self.token_introspection_url,
                                            data={'token': token},
                                            headers={'Accept': 'application/json'})
                   response.raise_for_status()
               except requests.exceptions.RequestException as e:
                   return ErrStr("Error while introspecting token: %s" % e)

               try:
                   data = response.json()
               except ValueError:
                   return ErrStr("Invalid response from token introspection URL.")

               if 'active' not in data:
                   return ErrStr("Invalid response from token introspection URL.")

               if not data['active']:
                   return ErrStr("Token is not active.")

               if scopes_required and'scope' in data:
                   scopes = data['scope'].split()
                   if not set(scopes_required).issubset(set(scopes)):
                       return ErrStr("Token does not contain required scopes.")

               return True

