def handle(cls, value, context, **kwargs):
        """Returns the value of a key for a given hook in hook_data.

        Format of value:

            <hook_name>::<key>
        """
            if not value:
                return None

            try:
                hook_name, key = value.split("::")
            except ValueError:
                raise ValidationError(
                    "Invalid hook key format. Expected <hook_name>::<key>."
                )

            try:
                hook_data = context["hook_data"]
            except KeyError:
                raise ValidationError(
                    "Hook data not found in context. Did you forget to call "
                    "the hook decorator?"
                )

            try:
                return hook_data[hook_name][key]
            except KeyError:
                raise ValidationError(
                    "Hook data for hook '{}' does not contain key '{}'.".format(
