def _retrieve(self, map):
        """Query Squid Proxy Server Manager Interface for stats.

        @param map: Statistics map name.
        @return:    Dictionary of query results.

        """
        # Build query string.
        query = "http://%s:%s/squid-cgi/squid_manager?mode=retrieve&map=%s" % (
            self.host, self.port, map)

        # Retrieve data.
        try:
            response = urllib2.urlopen(query)
            data = response.read()
            response.close()
        except urllib2.URLError, e:
            raise Exception("Unable to retrieve data from Squid Proxy Server Manager: %s" % e)

        # Parse data.
        try:
            data = json.loads(data)
        except ValueError, e:
            raise Exception("Unable to parse data from Squid Proxy Server Manager: %s" % e)

        # Return data.
        return data

