def _parse_website_config(self, (response, xml_bytes)):
        """Parse a C{WebsiteConfiguration} XML document."""
        if response.status!= 200:
            raise errors.HTTPError(response.status, response.reason,
                                   response.msg, response.headers)
        try:
            xml = etree.fromstring(xml_bytes)
        except etree.XMLSyntaxError as e:
            raise errors.HTTPError(500, "XML Syntax Error", e, {})

        # Parse the XML
        website_config = WebsiteConfiguration()
        website_config.parse(xml)
        return website_config

