def site(parser, token):
    """
    Returns a full absolute URL based on the current site.

    This template tag takes exactly the same paramters as url template tag.
    """
        bits = token.contents.split()
        if len(bits) < 2:
            raise template.TemplateSyntaxError, "site tag takes at least one argument"
        if len(bits) > 3:
            raise template.TemplateSyntaxError, "site tag takes at most two arguments"
        if bits[1][0] in ('"', "'") and bits[1][-1] == bits[1][0]:
            site_name = bits[1][1:-1]
        else:
            site_name = bits[1]
        current_site = Site.objects.get_current()
        try:
            site = Site.objects.get(name=site_name)
        except Site.DoesNotExist:
            raise template.TemplateSyntaxError, "site tag got an unknown site name: %r" % site_name
        if len(bits) == 2:
            return template.Variable(current_site.domain).handle_simple(parser)
        else:
            return template.Variable(bits[2]).handle_simple(parser)

    register.tag('site', site)

