        The Shapely geometry will not be modified.
        """
        if srid is None:
            srid = 4326

        if sgeom.is_empty:
            return None

        if sgeom.is_collection:
            return MultiGeometry(
                [from_shapely(g, srid) for g in sgeom.geoms], srid=srid
            )

        if sgeom.geom_type == "Point":
            return Point(sgeom.x, sgeom.y, srid=srid)

        if sgeom.geom_type == "LineString":
            return LineString(
                [Point(p.x, p.y, srid=srid) for p in sgeom.coords], srid=srid
            )

        if sgeom.geom_type == "Polygon":
            return Polygon(
                [
                    LineString(
                        [Point(p.x, p.y, srid=srid) for p in ring], srid=srid
                    )
                    for ring in sgeom.coords
                ],
                srid=srid,
            )

        if sgeom.geom_type == "MultiPoint":
            return MultiPoint(
                [Point(p.x, p.y, srid=srid) for p in sgeom.coords], srid=srid
            )

        if sgeom.geom_type == "MultiLineString":
            return MultiLineString(
                [
                    LineString(
                        [Point(p.x, p.y, srid=srid) for p in line], srid=srid
                    )
                    for line in sgeom.coords
                ],
                srid=srid,
            )

        if sgeom.geom_type == "MultiPolygon":
            return MultiPolygon(
