def _token_set(s1, s2, partial=True, force_ascii=True, full_process=True):
    """Find all alphanumeric tokens in each string...
        - treat them as a set
        - construct two strings of the form:
            <sorted_intersection><sorted_remainder>
        - take ratios of those two strings
        - controls for unordered partial matches"""
        if not partial:
            return _token_set_partial(s1, s2, force_ascii=force_ascii, full_process=full_process)
        else:
            return _token_set_unordered(s1, s2, force_ascii=force_ascii, full_process=full_process)

