def statistics(self, axes=(), minmaxvalues=(), exclude=False, robust=True):
        """Calculate statistics for the image.

        Statistics are returned in a dict for the given axes.
        E.g. if axes [0,1] is given in a 3-dim image, the statistics are
        calculated for each plane along the 3rd axis. By default statistics
        are calculated for the entire image.

        `minmaxvalues` can be given to include or exclude pixels
        with values in the given range. If only one value is given,
        min=-abs(val) and max=abs(val).

        By default robust statistics (Median, MedAbsDevMed, and Quartile) are
        calculated too.
        """
        (val) is assumed.

                `exclude` can be set to True to exclude pixels with values
                in the given range from the statistics.

                `robust` can be set to False to disable robust statistics.
                """
                if not axes:
                    axes = range(self.ndim)
                if not minmaxvalues:
                    minmaxvalues = [None, None]
                if len(minmaxvalues) == 1:
                    minmaxvalues = [-abs(minmaxvalues[0]), abs(minmaxvalues[0])]
                if len(minmaxvalues) == 0:
                    minmaxvalues = [None, None]
                if len(minmaxvalues)!= 2:
                    raise ValueError('minmaxvalues must be a list of two values')
                if minmaxvalues[0] is None:
                    minmaxvalues[0] = -np.inf
                if minmaxvalues[1] is None:
                    minmaxvalues[1] = np.inf
                if exclude:
                    mask = np.logical_or(self.data < minmaxvalues[0],
                                         self.data > minmaxvalues[1])
                else:
                    mask = np.logical_and(self.data >= minmaxvalues[0],
                                          self.data <= minmaxvalues[1])
                if robust:
                    return self._statistics(axes, mask)
                else:
