def unparse(input_dict, output=None, encoding='utf-8', full_document=True,
            short_empty_elements=False,
            **kwargs):
    """Emit an XML document for the given `input_dict` (reverse of `parse`).

    The resulting XML document is returned as a string, but if `output` (a
    file-like object) is specified, it is written there instead.

    Dictionary keys prefixed with `attr_prefix` (default=`'@'`) are interpreted
    as XML node attributes, whereas keys equal to `cdata_key`
    (default=`'#text'`) are treated as character data.

    The `pretty` parameter (default=`False`) enables pretty-printing. In this
    mode, lines are terminated with `'\n'` and indented with `'\t'`, but this
    can be customized with the `newl` and `indent` parameters.

    """
    '##text'`) are interpreted as CDATA sections.

        If `full_document` is `True` (default), the XML document is wrapped in a
        root element. If `full_document` is `False`, the root element is not
        included.

        If `short_empty_elements` is `True` (default), empty elements are
        represented as empty tags (e.g. `<foo/>` instead of `<foo></foo>`).

        The `encoding` parameter is used to encode the resulting XML document.

        The `kwargs` are passed to `xml.dom.minidom.Document.toprettyxml`.
        """
        if output is None:
            output = StringIO()
        if full_document:
            root_element = input_dict.get(root_key)
            if root_element is None:
                root_element = input_dict
            input_dict = {root_key: root_element}
        else:
            root_element = None
        doc = xml.dom.minidom.Document()
        if root_element is not None:
            root = doc.createElement(root_element.get(tag_key, root_key))
            for key, value in root_element.items():
                if key.startswith(attr_prefix):
                    root.setAttribute(key[len(attr_prefix):], value)
                elif key == cdata_key:
                    root.appendChild(doc.createCDATASection(value))
                else:
                    root.appendChild(unparse_element(doc, key, value))
            doc.appendChild(root)
        else:
            for key, value in input_dict.items():
                doc.appendChild(unparse_element(doc, key, value))
        if kwargs:
            doc.toprettyxml(output, encoding=encoding, **kwargs)
        else:
