def http(klass, url, interval, timeout=None, deregister=None, header=None):
        """
        Peform a HTTP GET against *url* every *interval* (e.g. "10s") to peform
        health check with an optional *timeout* and optional *deregister* after
        which a failing service will be automatically deregistered. Optional
        parameter *header* specifies headers sent in HTTP request. *header*
        paramater is in form of map of lists of strings,
        e.g. {"x-foo": ["bar", "baz"]}.
        """
            if not isinstance(klass, Service):
                raise TypeError("klass must be a Service")
            if not isinstance(url, str):
                raise TypeError("url must be a string")
            if not isinstance(interval, str):
                raise TypeError("interval must be a string")
            if timeout is not None and not isinstance(timeout, str):
                raise TypeError("timeout must be a string")
            if deregister is not None and not isinstance(deregister, str):
                raise TypeError("deregister must be a string")
            if header is not None and not isinstance(header, dict):
                raise TypeError("header must be a dict")
            klass.add_check(
                Check.http(
                    url,
                    interval,
                    timeout=timeout,
                    deregister=deregister,
                    header=header,
                )
            )

