def endpoint_create(service, publicurl=None, internalurl=None, adminurl=None,
                    region=None, profile=None, url=None, interface=None, **connection_args):
    """
    Create an endpoint for an Openstack service

    CLI Examples:

    .. code-block:: bash

        salt 'v2' keystone.endpoint_create nova 'http://public/url' 'http://internal/url' 'http://adminurl/url' region

        salt 'v3' keystone.endpoint_create nova url='http://public/url' interface='public' region='RegionOne'
    """
    ='region'

            salt 'v3' keystone.endpoint_create nova url='http://public/url' interface='admin' region='region'

            salt 'v3' keystone.endpoint_create nova url='http://public/url' interface='internal' region='region'

            salt 'v3' keystone.endpoint_create nova url='http://public/url' interface='public' region='region' profile='profile'

            salt 'v3' keystone.endpoint_create nova url='http://public/url' interface='admin' region='region' profile='profile'

            salt 'v3' keystone.endpoint_create nova url='http://public/url' interface='internal' region='region' profile='profile'
        """
        if not profile:
            profile = 'default'
        if not url:
            url = publicurl
        if not interface:
            interface = 'public'
        if not region:
            region = 'RegionOne'
        if not adminurl:
            adminurl = internalurl
        if not internalurl:
            internalurl = publicurl
        if not connection_args:
            connection_args = {}
        if 'v3' in service:
            return _endpoint_create_v3(service, url, interface, region, profile, adminurl, **connection_args)
        else:
            return _endpoint_create_v2(service, url, internalurl, adminurl, region, profile, **connection_args)

